export class ParticleBackground{constructor(t){this.container=t,this.colors=this.getColorsFromAttributes(),this.particleCount=parseInt(t.dataset.count)||60,this.animationSpeed=parseFloat(t.dataset.speed)||1,this.init()}getColorsFromAttributes(){let t=[];for(let i=1;i<=5;i++){let e=this.container.dataset[`color${i}`]||this.container.dataset[`color-${i}`];e&&t.push(e)}return t.length>0?t:["#00d76c","#a8e2ff","#ffffff"]}init(){this.canvas=document.createElement("canvas"),this.container.appendChild(this.canvas),this.ctx=this.canvas.getContext("2d"),this.resize(),window.addEventListener("resize",this.resize.bind(this)),this.particles=[];for(let t=0;t<this.particleCount;t++)this.particles.push(this.createParticle());this.animate()}createParticle(){return{x:Math.random()*this.width,y:Math.random()*this.height,size:3*Math.random()+1,color:this.colors[Math.floor(Math.random()*this.colors.length)],speed:Math.random()*this.animationSpeed+.2,direction:Math.random()*Math.PI*2}}resize(){this.width=this.canvas.width=this.container.offsetWidth,this.height=this.canvas.height=this.container.offsetHeight}animate(){this.ctx.clearRect(0,0,this.width,this.height),this.particles.forEach(t=>{t.x+=Math.cos(t.direction)*t.speed,t.y+=Math.sin(t.direction)*t.speed,(t.x<0||t.x>this.width)&&(t.direction=Math.PI-t.direction),(t.y<0||t.y>this.height)&&(t.direction=-t.direction),this.ctx.fillStyle=t.color,this.ctx.beginPath(),this.ctx.arc(t.x,t.y,t.size,0,2*Math.PI),this.ctx.fill()}),requestAnimationFrame(this.animate.bind(this))}}document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".particle-background").forEach(t=>{new ParticleBackground(t)})});